def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Uniform rows/columns act as separators.
    divider_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    divider_cols = [
        c for c in range(w)
        if len({grid[r][c] for r in range(h)}) == 1
    ]

    def intervals(size, dividers):
        result = []
        start = 0
        for d in dividers:
            result.append((start, d))
            start = d + 1
        result.append((start, size))
        return result

    rows = intervals(h, divider_rows)
    cols = intervals(w, divider_cols)
    rbase0, rbase1 = rows[0]
    cbase0, cbase1 = cols[0]

    # The most common color in the source compartment is its background.
    from collections import Counter
    counts = Counter(
        grid[r][c]
        for r in range(rbase0, rbase1)
        for c in range(cbase0, cbase1)
    )
    background = counts.most_common(1)[0][0]

    for ri, (r0, r1) in enumerate(rows):
        for ci, (c0, c1) in enumerate(cols):
            for r in range(rbase0, rbase1):
                rr = r0 + (r - rbase0 if ri % 2 == 0 else rbase1 - 1 - r)
                for c in range(cbase0, cbase1):
                    value = grid[r][c]
                    if value == background:
                        continue
                    cc = c0 + (c - cbase0 if ci % 2 == 0 else cbase1 - 1 - c)
                    if r0 <= rr < r1 and c0 <= cc < c1:
                        out[rr][cc] = value
    return out
